	/**
	 * Method to retrieve the ClinicalOrder via ClinicalOrderFetchOneSummary
	 * @param 	summary ClinicalOrderFetchOneSummary
	 * @return 	ClinicalOrderFetchOneResponse
	 */
	public ClinicalOrder getClinicalOrder( ClinicalOrderFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ClinicalOrderFetchOneSummary arg cannot be null" );

		ClinicalOrder entity = null;
		UUID id = summary.getClinicalOrderId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ClinicalOrder using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


